from urllib.parse import urlparse, parse_qs, urlencode, urlunparse
from typing import List, Dict, Optional

def apply_rewrite_rules(rules: List[Dict], urls: List[str]) -> List[Optional[str]]:
    def process_url(url: str, rules: List[Dict]) -> Optional[str]:
        parsed = urlparse(url)

        for rule in rules:
            match_type = rule.get("match_type")
            match_value = rule.get("match_value", "")
            action = rule.get("action")
            action_value = rule.get("action_value", "")

            matched = False

            if match_type == "path_prefix":
                if parsed.path.startswith(match_value):
                    matched = True

            elif match_type == "host":
                if parsed.hostname == match_value:
                    matched = True
                elif match_value.startswith("*.") and parsed.hostname.endswith(match_value[1:]):
                    matched = True

            elif match_type == "query_param":
                query_params = parse_qs(parsed.query)
                if match_value in query_params:
                    matched = True

            if not matched:
                continue

            # action 実行
            if action == "strip_prefix":
                new_path = parsed.path[len(match_value):]
                if not new_path:
                    new_path = "/"

                return urlunparse((
                    parsed.scheme,
                    parsed.netloc,
                    new_path,
                    parsed.params,
                    parsed.query,
                    parsed.fragment
                ))

            elif action == "redirect_host":
                netloc = f"{match_value}{parsed.path.split('/')[-1]}" if "/" in match_value else match_value
                return urlunparse((
                    parsed.scheme,
                    netloc + parsed.netloc.split(":"),  # port を維持しつつ置き換え
                    parsed.params,
                    parsed.params,
                    parsed.query,
                    parsed.fragment
                ))

            elif action == "add_query_param":
                current_params = parse_qs(parsed.query)
                key_value = action_value
                if "=" in key_value:
                    key, value = key_value.split("=", 1)
                    new_params = dict(current_params)
                    if key not in new_params:
                        new_params[key] = [value]

                    # 重複キーがある場合の処理（解析されたクエリを保持）
                    for k, v in current_params.items():
                        if isinstance(v, list):
                            new_params[k] = v
                        else:
                            new_params[k] = [v]

                    result_query = urlencode(new_params, doseq=True)
                else:
                    # 値付きのみの場合（例："key"）-> "key=value"と解釈するか
                    new_params = dict(current_params)
                    if action_value and "=" not in action_value:
                        new_params[action_value] = [""]
                    result_query = urlencode(new_params, doseq=True)

                return urlunparse((
                    parsed.scheme,
                    parsed.netloc,
                    parsed.path,
                    "",
                    result_query,
                    parsed.fragment
                ))

            elif action == "block":
                return None

        # ルールに適合しない場合
        return url

    results = [process_url(url, rules) for url in urls]
    return results
